import{c as a,Q as e,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"IBSet","description":"","frontmatter":{},"headers":[{"level":1,"title":"IBSet","slug":"ibset"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/同步控制/核间同步/IBSet.md","filePath":"api/SIMD-API/基础API/同步控制/核间同步/IBSet.md"}'),n={name:"api/SIMD-API/基础API/同步控制/核间同步/IBSet.md"};function d(i,t,r,o,p,c){return e(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="ibset" tabindex="-1">IBSet <a class="header-anchor" href="#ibset" aria-label="Permalink to &quot;IBSet&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>当不同核之间操作同一块全局内存且可能存在读后写、写后读以及写后写等数据依赖问题时，通过调用该函数来插入同步语句来避免上述数据依赖时可能出现的数据读写错误问题。调用IBSet设置某一个核的标志位，与IBWait成对出现配合使用，表示核之间的同步等待指令，等待某一个核操作完成。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool isAIVOnly = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void IBSet(const GlobalTensor&lt;int32_t&gt;&amp; gmWorkspace, const LocalTensor&lt;int32_t&gt;&amp; ubWorkspace, int32_t blockIdx, int32_t eventID)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>isAIVOnly</td><td>控制是否为AIVOnly模式，默认为true。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>gmWorkspace</td><td>输出</td><td>外部存储核状态的公共缓存，类型为GlobalTensor。GlobalTensor数据结构的定义请参考GlobalTensor。</td></tr><tr><td>ubWorkspace</td><td>输入</td><td>存储当前核状态的公共缓存。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>blockIdx</td><td>输入</td><td>表示等待核的idx号，取值范围：[0, 核数-1]。</td></tr><tr><td>eventID</td><td>输入</td><td>用来控制当前核的set、wait事件。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>gmWorkspace申请的空间最少要求为：核数 * 32Bytes * eventID_max + blockIdx_max * 32Bytes + 32Bytes。（eventID_max和blockIdx_max分别指eventID、blockIdx的最大值 ）；</li><li>注意：如果是AIVOnly模式，核数 = GetBlockNum()；如果是MIX模式，核数 = GetBlockNum() * 2；</li><li>ubWorkspace申请的空间最少要求为：32Bytes；</li><li>gmWorkspace缓存的值需要初始化为0。</li><li>使用该接口进行多核控制时，算子调用时指定的逻辑numBlocks必须保证不大于实际运行该算子的AI处理器核数，否则框架进行多轮调度时会插入异常同步，导致Kernel“卡死”现象。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本示例实现功能为使用2个核进行数据处理，每个核均是处理256个half类型数据。核0实现x+y的操作，并将结果放入z的前半部分，核1将核0的计算结果放入x，之后与y相加，结果存入z的后半部分，因此多个核之间需要进行数据同步。如需运行，请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/06_sync_control/ib_set_wait" target="_blank" rel="noreferrer">IBSet与IBWait核间同步样例</a>实现完整的代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// sync_gm为外部存储核状态的公共缓存，类型为GlobalTensor；sync_buf为存储当前核状态的公共缓存，类型为LocalTensor</span></span>
<span class="line"><span>int32_t blockIdx = AscendC::GetBlockIdx(); // 获取当前核</span></span>
<span class="line"><span>if (blockIdx == 1) { // 在核1设置IBWait，将阻塞指令执行直到核0操作完成</span></span>
<span class="line"><span>    AscendC::IBWait(sync_gm, sync_buf, 0, 0);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>if (blockIdx == 0) { // 在核0设置IBSet，当核0的操作完成后再执行核1的指令</span></span>
<span class="line"><span>    AscendC::IBSet(sync_gm, sync_buf, 0, 0);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,19)])])}const u=a(n,[["render",d]]);export{b as __pageData,u as default};
